<?php $ci =& get_instance(); $types=['all'=>'All offerings','plant'=>'Living plants','supply'=>'Supplies & accessories','service'=>'Services','bundle'=>'Bundles']; $totals=$garden_catalogue_counts ?? array_fill_keys(array_keys($types),0); ?>
<section class="garden-panel">
<div class="garden-panel-heading"><div><span class="garden-kicker">FROM NURSERY TO CUSTOMER</span><h2>Plants, supplies & services</h2></div><?php if ($ci->permissions('items_add')): ?><a class="garden-button garden-catalogue-add" href="<?= base_url('items/add'); ?>"><i class="fa fa-plus" aria-hidden="true"></i> Add offering</a><?php endif; ?></div>
<p class="garden-panel-intro garden-muted">Manage your shared catalogue. Living plants carry care details; services have no stock balance. Showing 10 active offerings per page.</p>
<div class="garden-catalogue-toolbar"><div class="garden-catalogue-tabs" role="group" aria-label="Filter catalogue"><?php foreach ($types as $key=>$label): ?><button type="button" class="garden-type-filter <?= $key==='all' ? 'is-selected' : ''; ?>" data-kind="<?= $key; ?>" aria-pressed="<?= $key==='all' ? 'true' : 'false'; ?>"><?= $label; ?> <span><?= (int)($totals[$key] ?? 0); ?></span></button><?php endforeach; ?></div><form method="get" action="<?= base_url('garden/catalogue'); ?>" class="garden-catalogue-search"><span class="sr-only">Find an offering by name or code</span><?php if($this->input->get('screen')==='mobile'): ?><input type="hidden" name="screen" value="mobile"><?php endif; ?><input type="search" id="garden-catalogue-search" name="q" value="<?= htmlspecialchars($garden_catalogue_query ?? '',ENT_QUOTES,'UTF-8'); ?>" placeholder="Search name or code…"></form></div>
<div class="garden-table-wrap"><table><thead><tr><th>Name / code</th><th>Type</th><th>Available stock</th><th></th></tr></thead><tbody>
<?php foreach ($garden_items as $item): $kind=$item->attributes_json!==null ? 'plant' : (!empty($item->is_bundle) ? 'bundle' : ((int)$item->service_bit===1 ? 'service' : 'supply')); ?><tr data-garden-offering data-kind="<?= $kind; ?>"><td class="garden-cell-title"><span class="garden-item-name"><?= htmlspecialchars($item->item_name); ?></span><small><?= htmlspecialchars($item->item_code); ?></small></td><td data-label="Type"><span class="garden-pill"><?= ['plant'=>'Living plant','supply'=>'Supply / accessory','service'=>'Service / non-stock','bundle'=>'Bundle'][$kind]; ?></span></td><td data-label="Available stock"><?= (int)$item->service_bit===1 || !empty($item->is_bundle) ? '—' : htmlspecialchars($item->stock); ?></td><td class="garden-row-actions"><?php if ($ci->permissions('items_edit')): ?><a href="<?= base_url('items/update/'.(int)$item->id); ?>">Edit</a><?php if ((int)$item->service_bit!==1 && empty($item->is_bundle)): ?><a href="<?= base_url('garden/plant/'.(int)$item->id); ?>"><?= $kind==='plant' ? 'Plant care details' : 'Set up as living plant'; ?></a><?php endif; ?><?php endif; ?></td></tr><?php endforeach; ?>
<tr id="garden-catalogue-empty" <?= $garden_items ? 'hidden' : ''; ?>><td colspan="4"><div class="garden-empty"><i class="fa fa-pagelines" aria-hidden="true"></i><h3>No matching offerings</h3><p>Add an offering or try another search or category.</p></div></td></tr>
</tbody></table></div><p id="garden-catalogue-count" class="garden-muted garden-panel-intro" role="status"><?= count($garden_items); ?> of <?= (int)($garden_catalogue_total ?? count($garden_items)); ?> offerings shown</p>
<?php if(($garden_catalogue_pages ?? 1)>1): ?><nav class="garden-report-pager garden-catalogue-pager" aria-label="Catalogue pages"><?php $catalogue_params=['q'=>$garden_catalogue_query ?? '','screen'=>$this->input->get('screen')]; ?><?php if(($garden_catalogue_page ?? 1)>1): ?><a class="garden-button garden-button-secondary" href="<?= htmlspecialchars(base_url('garden/catalogue').'?'.http_build_query(array_filter($catalogue_params+['page'=>$garden_catalogue_page-1],function($v){return $v!==null&&$v!=='';})),ENT_QUOTES,'UTF-8'); ?>">Previous</a><?php endif; ?><span class="garden-muted" role="status">Page <?= (int)$garden_catalogue_page; ?> of <?= (int)$garden_catalogue_pages; ?></span><?php if($garden_catalogue_page<$garden_catalogue_pages): ?><a class="garden-button garden-button-secondary" href="<?= htmlspecialchars(base_url('garden/catalogue').'?'.http_build_query(array_filter($catalogue_params+['page'=>$garden_catalogue_page+1],function($v){return $v!==null&&$v!=='';})),ENT_QUOTES,'UTF-8'); ?>">Next</a><?php endif; ?></nav><?php endif; ?></section>
